# ---- verification ----
def d(r, c): return isqrt(r * r - (c // 2) ** 2)
assert d(10, 16) == 6 and d(13, 10) == 12 and d(5, 8) == 3 and d(13, 24) == 5 and 13 - 5 == 8 and 13 + 5 == 18
assert d(10, 12) == 8 and d(10, 16) == 6 and 8 + 6 == 14 and 8 - 6 == 2
assert 100 // 2 == 50 and 360 - 100 == 260 and 180 - 50 == 130
assert 5 * 38 - 10 == 180 and 2 * 38 + 10 == 86 and 3 * 38 - 20 == 94
assert 180 - 70 == 110 and 180 - 95 == 85 and 180 - 80 == 100
assert d(17, 30) == 8 and d(17, 16) == 15 and 8 + 15 == 23 and 15 - 8 == 7
assert d(15, 24) == 9 and d(15, 18) == 12 and 9 + 12 == 21
assert d(20, 32) == 12 and 20 - 12 == 8 and d(10, 16) == 6
assert 3 * 20 + 10 == 5 * 20 - 30 == 70
assert 12 ** 2 + (13 - 8) ** 2 == 13 ** 2 and 16 * 13 == 208 and 12 * 12 + 64 == 208
assert 10 ** 2 + 24 ** 2 == 26 ** 2 and 2 * (10 * 24 // 2) == 240
assert 10 * 15 + 30 == 180 and 6 * 15 + 10 == 100 and 4 * 15 + 20 == 80 and 5 * 15 == 75 and 75 + 105 == 180
assert 75 + 105 == 180 and 95 + 85 == 180
assert 8 ** 2 + 6 ** 2 == 10 ** 2 and (4, 3) == (8 // 2, 6 // 2)
assert 12 ** 2 - 6 ** 2 == 108 and 20 ** 2 + 20 ** 2 == 800 and 90 // 2 == 45

